/**
 * Asset manifest: generated by scripts/build-assets.ts, served without caching. Every file it
 * points to has a content hash in its name and can be cached forever by the CDN.
 */
import { z } from 'zod';

const HashedFile = z.strictObject({ url: z.string().min(1), bytes: z.int().min(0) });

export const AssetManifestSchema = z.strictObject({
  version: z.literal(1),
  groups: z.record(
    z.string(),
    z.strictObject({
      demo: z.boolean(),
      atlases: z.array(
        z.strictObject({
          key: z.string(),
          image: HashedFile,
          data: HashedFile,
          /** Normal map for Phaser lighting (generated from the art, docs/systems/light.md). */
          normal: HashedFile.optional(),
        }),
      ),
      /** Each sound has an Ogg Vorbis file and an AAC (m4a) fallback for Safari. */
      audio: z.array(z.strictObject({ key: z.string(), ogg: HashedFile, m4a: HashedFile })),
    }),
  ),
  /** Zone id → asset groups it needs (loaded lazily when the zone is entered). */
  zones: z.record(z.string(), z.array(z.string())),
  /** Tiled maps by content path ("maps/village.tmj") with their tilesets (docs/systems/maps.md). */
  maps: z
    .record(
      z.string(),
      z.strictObject({
        data: HashedFile,
        tilesets: z.record(z.string(), z.strictObject({ image: HashedFile, normal: HashedFile })),
      }),
    )
    .default({}),
});
export type AssetManifest = z.infer<typeof AssetManifestSchema>;
export type AssetGroup = AssetManifest['groups'][string];

/** Groups loaded before the main menu. */
export const BASE_GROUPS = ['common'] as const;

export function groupsForZone(manifest: AssetManifest, zone: string): string[] {
  return manifest.zones[zone] ?? [];
}

export function bytesOfGroups(manifest: AssetManifest, groups: readonly string[]): number {
  return groups.reduce((sum, name) => {
    const g = manifest.groups[name];
    if (!g) return sum;
    const atlas = g.atlases.reduce(
      (s, a) => s + a.image.bytes + a.data.bytes + (a.normal?.bytes ?? 0),
      0,
    );
    // Only one of the two audio formats is downloaded.
    const audio = g.audio.reduce((s, a) => s + Math.max(a.ogg.bytes, a.m4a.bytes), 0);
    return sum + atlas + audio;
  }, 0);
}

/** Bytes of a zone map with its tilesets (and normal maps). */
export function bytesOfMap(manifest: AssetManifest, path: string): number {
  const map = manifest.maps[path];
  if (!map) return 0;
  return (
    map.data.bytes +
    Object.values(map.tilesets).reduce((s, t) => s + t.image.bytes + t.normal.bytes, 0)
  );
}
